// Actions-only API DATA projection and explicit Info config. SQL fixtures do not
// represent SDK/body consumption, authorize replies, or start a receiver.
#[tokio::test]
async fn im_info_http_opt_in_is_strict_default_false_and_never_implicit_sdk_or_business_start(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let base=im_runtime_config_json(&cert.root);
    for value in [serde_json::Value::Null,serde_json::json!(0),serde_json::json!("true"),serde_json::json!({"grant":"fixture-must-not-echo"})]{let mut config=base.clone();config["profile"]["native_receivers"]["im_messages"]["receive_info"]=value;
        let(status,headers,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":config})),Some(&cookie)).await;assert_eq!(status,StatusCode::BAD_REQUEST);no_store(&headers);no_secrets(&body);assert!(!body.contains("fixture-must-not-echo"));}
    for enabled in [None,Some(false),Some(true)]{let mut config=base.clone();if let Some(value)=enabled{config["profile"]["native_receivers"]["im_messages"]["receive_info"]=serde_json::json!(value);}
        let(status,headers,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":config})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);no_store(&headers);no_secrets(&body);let line=created_line(&body);let view=state.app.app_accounts.get(&line,100).await.unwrap();assert_eq!(view.phase,"stopped");assert!(!view.incoming_message_ready&&!view.incoming_call_ready&&!view.outbound_authorized&&!view.io_cleanup_required);
        let(status,headers,body)=account_request(&served,reqwest::Method::GET,&format!("/api/non-3gpp/accounts/{line}/im-messages?limit=128"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);no_secrets(&body);assert_eq!(serde_json::from_str::<serde_json::Value>(&body).unwrap()["data"],serde_json::json!([]));}
    let leases:i64=state.app.database.with_conn(|c|c.query_row("SELECT COUNT(*) FROM app_voice_runtime_leases",[],|r|r.get(0)).map_err(|_|"fixture")).unwrap();assert_eq!(leases,0);
}
#[tokio::test]
async fn im_info_http_typed_history_hides_private_epoch_and_delete_preserves_only_tombstone_data(){
    let state=build_test_router().await.expect("Actions private D-Bus required; no skip");let served=serve(state.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let mut config=im_runtime_config_json(&cert.root);config["profile"]["native_receivers"]["im_messages"]["receive_info"]=serde_json::json!(true);
    let(status,_,body)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":config})),Some(&cookie)).await;assert_eq!(status,StatusCode::CREATED);let line=created_line(&body);
    let id=state.app.database.with_conn(|conn|{conn.execute("INSERT INTO app_voice_im_messages(line_id,revision,identity_key,box_id,box_kind,message_index,fingerprint,original_time,body,text,sender,attachment_count,created_at,body_kind,info_type,system_info,info_epoch) VALUES(?1,1,?2,?3,'p2p',?4,?5,0,?6,'visible Info content',?7,1,'2026-01-01T00:00:00Z','info',?8,1,?9)",rusqlite::params![line,vec![7u8;32],b"P2P/1_2".as_slice(),i64::MAX,vec![8u8;32],b"private-info-raw".as_slice(),b"private-info-sender".as_slice(),b"Notice".as_slice(),"a".repeat(32)]).map_err(|_|"fixture")?;Ok(conn.last_insert_rowid())}).unwrap();
    let path=format!("/api/non-3gpp/accounts/{line}/im-messages");let(status,headers,body)=account_request(&served,reqwest::Method::GET,&path,None,Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);no_secrets(&body);let value:serde_json::Value=serde_json::from_str(&body).unwrap();let row=&value["data"][0];assert_eq!(row.as_object().unwrap().len(),9);assert_eq!(row["kind"],"info");assert_eq!(row["info_type"],"Notice");assert_eq!(row["system_info"],true);assert_eq!(row["text"],"visible Info content");assert_eq!(row["message_index"],"9223372036854775807");
    for private in ["private-info-raw","private-info-sender","P2P/1_2","identity_key","fingerprint","info_epoch","body_kind"]{assert!(!body.contains(private));}
    state.app.database.with_conn(|c|c.execute("UPDATE app_voice_im_messages SET info_type=?1 WHERE id=?2",rusqlite::params![b"bad/type".as_slice(),id]).map_err(|_|"fixture")).unwrap();let(status,headers,body)=account_request(&served,reqwest::Method::GET,&path,None,Some(&cookie)).await;assert_eq!(status,StatusCode::INTERNAL_SERVER_ERROR);no_store(&headers);no_secrets(&body);assert!(!body.contains("bad/type"));
    state.app.database.with_conn(|c|c.execute("UPDATE app_voice_im_messages SET info_type=?1 WHERE id=?2",rusqlite::params![b"Notice".as_slice(),id]).map_err(|_|"fixture")).unwrap();
    let(status,headers,body)=account_request(&served,reqwest::Method::DELETE,&format!("{path}/{id}"),None,Some(&cookie)).await;assert_eq!(status,StatusCode::OK);no_store(&headers);assert_eq!(serde_json::from_str::<serde_json::Value>(&body).unwrap()["data"],true);
    let(_,headers,body)=account_request(&served,reqwest::Method::GET,&path,None,Some(&cookie)).await;no_store(&headers);assert_eq!(serde_json::from_str::<serde_json::Value>(&body).unwrap()["data"],serde_json::json!([]));
    let remaining:(i64,i64,Option<Vec<u8>>,i64,i64,i64)=state.app.database.with_conn(|c|c.query_row("SELECT deleted,length(body)+length(CAST(text AS BLOB))+length(sender),info_type,system_info,length(fingerprint),length(CAST(info_epoch AS BLOB)) FROM app_voice_im_messages WHERE id=?1",[id],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?,r.get(4)?,r.get(5)?))).map_err(|_|"fixture")).unwrap();assert_eq!(remaining,(1,0,None,0,32,32));assert!(state.app.app_accounts.messages(&line,16).unwrap().is_empty());let view=state.app.app_accounts.get(&line,100).await.unwrap();assert_eq!(view.phase,"stopped");assert!(!view.incoming_message_ready&&!view.incoming_call_ready&&!view.outbound_authorized);
}
